35	import static org.apache.hudi.config.DynamoDbBasedLockConfig.MAX_PARTITION_KEY_SIZE_BYTE;
36	
37	/**
38	 * A DynamoDB based lock.
39	 * It implicitly derives the partition key from the hudi table name and hudi table base path
40	 * available in the lock configuration.
41	 */
42	@NotThreadSafe
43	public class DynamoDBBasedImplicitPartitionKeyLockProvider extends DynamoDBBasedLockProviderBase {
44	  protected static final Logger LOG = LoggerFactory.getLogger(DynamoDBBasedImplicitPartitionKeyLockProvider.class);
45	
46	  public DynamoDBBasedImplicitPartitionKeyLockProvider(final LockConfiguration lockConfiguration, final StorageConfiguration<?> conf) {
47	    this(lockConfiguration, conf, null);
48	  }
49	
50	  public DynamoDBBasedImplicitPartitionKeyLockProvider(
51	      final LockConfiguration lockConfiguration, final StorageConfiguration<?> conf, DynamoDbClient dynamoDB) {
52	    super(lockConfiguration, conf, dynamoDB);
53	  }
54	
55	  public static String generatePartitionKey(String basePath, String tableName) {
56	    String hashPart = '-' + HashID.generateXXHashAsString(basePath, HashID.Size.BITS_64);
57	    String partitionKey = concatenateWithThreshold(tableName, hashPart, MAX_PARTITION_KEY_SIZE_BYTE);
58	    LOG.info(String.format("The DynamoDB partition key of the lock provider for the base path %s is %s", basePath, partitionKey));
59	    return partitionKey;
60	  }
61	
62	  @Override
63	  public String getDynamoDBPartitionKey(LockConfiguration lockConfiguration) {
64	    String hudiTableBasePath = lockConfiguration.getConfig().getString(HoodieCommonConfig.BASE_PATH.key());
65	    String hudiTableName = lockConfiguration.getConfig().getString(HoodieTableConfig.HOODIE_TABLE_NAME_KEY);
66	    // Ensure consistent format for S3 URI.
67	    return generatePartitionKey(s3aToS3(hudiTableBasePath), hudiTableName);
68	  }
69	}
